#include <stdio.h>
#include <string.h>
int main() {
    char exp[1001], stack[1001];
    int top = -1, i = 0, valid = 1;
    if(scanf("%1000s", exp) != 1) return 0;
    while(exp[i]) {
        if(exp[i] == '(' || exp[i] == '{' || exp[i] == '[') {
            stack[++top] = exp[i];
        } else if(exp[i] == ')' || exp[i] == '}' || exp[i] == ']') {
            if(top == -1) { valid = 0; break; }
            if(exp[i] == ')' && stack[top] != '(') { valid = 0; break; }
            if(exp[i] == '}' && stack[top] != '{') { valid = 0; break; }
            if(exp[i] == ']' && stack[top] != '[') { valid = 0; break; }
            top--;
        }
        i++;
    }
    if(top != -1) valid = 0;
    if(valid) printf("Balanced");
    else printf("Not Balanced");
    return 0;
}

#include <stdio.h>
#include <string.h>
int queue[100], front = -1, rear = -1, size;
void enqueue(int v) {
    if ((rear + 1) % size == front) printf("Queue is Full\n");
    else {
        if (front == -1) front = 0;
        rear = (rear + 1) % size;
        queue[rear] = v;
    }
}
void dequeue() {
    if (front == -1) printf("Queue is Empty\n");
    else {
        printf("%d\n", queue[front]);
        if (front == rear) { front = -1; rear = -1; }
        else front = (front + 1) % size;
    }
}
void display() {
    if (front == -1) printf("Empty\n");
    else {
        int i = front;
        while (1) {
            printf("%d%c", queue[i], i == rear ? '\n' : ' ');
            if (i == rear) break;
            i = (i + 1) % size;
        }
    }
}
int main() {
    int ops, v;
    char op[20];
    if(scanf("%d %d", &size, &ops) != 2) return 0;
    while(ops--) {
        scanf("%s", op);
        if(!strcmp(op, "enqueue")) { scanf("%d", &v); enqueue(v); }
        else if(!strcmp(op, "dequeue")) dequeue();
        else if(!strcmp(op, "display")) display();
    }
    return 0;
}
